INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('grenovales/printful-client/github', 'community', 'grenovales', 'printful-client', 'grenovales/printful-client', 'github', 0, 0, 0, '2026-02-18T01:08:43.471Z', '2026-02-18T08:53:09.197Z', NULL, '{"id":"grenovales/printful-client/github","name":"github","description":{"zh":"GitHub SDK Wrapper for Printful API. Create pull requests and merges with GitHub CLI.","ja":"GitHub SDK Wrapper Printful API GitHub CLI","ko":"GitHub SDK Wrapper Printful API GitHub CLI","es":"El SDK de GitHub para Printful API permite a los desarrolladores interactuar con GitHub de manera eficiente. Crea solicitudes de extracción y fusiones con facilidad","fr":"Le wrapper SDK GitHub pour Printful API permet aux développeurs d''interagir avec GitHub de manière efficace. Créez des demandes d''extraction et des fusions avec facilité","de":"Der GitHub SDK-Wrapper für Printful API ermöglicht es Entwicklern, mit GitHub effizient zu interagieren. Erstellen Sie Pull-Requests und Merge-Anfragen mit Leichtigkeit","pt":"O GitHub SDK é uma ferramenta para interagir com a Printful API, permitindo criar pull requests e merges de forma eficiente","ru":"GitHub SDK - это инструмент для взаимодействия с Printful API, позволяющий создавать запросы на слияние и объединения эффективно","ar":"جيت هاب SDK هو أداة للتفاعل مع Printful API، مما يسمح بإنشاء طلبات سحب ودمج بشكل فعال","en":"SDK Wrapper for the Printful API"},"seo":{"title":{"zh":"GitHub SDK Wrapper - Printful API","ja":"GitHub SDK Wrapper - Printful API","ko":"GitHub SDK - Printful API","es":"SDK de GitHub para Printful API","fr":"Wrapper SDK GitHub pour Printful API","de":"GitHub SDK-Wrapper für Printful API","pt":"GitHub SDK: Integração com Printful API","ru":"GitHub SDK: Оболочка для Printful API","ar":"جيت هاب SDK: غطاء Printful API","en":"github"},"description":{"zh":"GitHub SDK Wrapper for Printful API. Create pull requests and merges with GitHub CLI.","ja":"GitHub SDK Wrapper Printful API GitHub CLI","ko":"GitHub SDK Wrapper Printful API GitHub CLI","es":"El SDK de GitHub para Printful API permite a los desarrolladores interactuar con GitHub de manera eficiente. Crea solicitudes de extracción y fusiones con fa...","fr":"Le wrapper SDK GitHub pour Printful API permet aux développeurs d''interagir avec GitHub de manière efficace. Créez des demandes d''extraction et des fusions a...","de":"Der GitHub SDK-Wrapper für Printful API ermöglicht es Entwicklern, mit GitHub effizient zu interagieren. Erstellen Sie Pull-Requests und Merge-Anfragen mit L...","pt":"O GitHub SDK é uma ferramenta para interagir com a Printful API, permitindo criar pull requests e merges de forma eficiente","ru":"GitHub SDK - это инструмент для взаимодействия с Printful API, позволяющий создавать запросы на слияние и объединения эффективно","ar":"جيت هاب SDK هو أداة للتفاعل مع Printful API، مما يسمح بإنشاء طلبات سحب ودمج بشكل فعال","en":"SDK Wrapper for the Printful API"},"definition":{"en":"SDK Wrapper for the Printful API"},"features":{"zh":["GitHub CLI","Printful API SDK Wrapper","Pull Request","Merge","Interactive Prompts","Non-interactive Mode"],"ja":["GitHub CLI","Printful API SDK Wrapper","Pull Request","Merge","Interactive","Non-interactive"],"ko":["GitHub CLI","Printful API SDK Wrapper","Pull Request","Merge","","Non-interactive"],"es":["Crea solicitudes de extracción de manera interactiva","Establece títulos y descripciones personalizados para solicitudes de extracción","Selecciona ramas base y revisores para solicitudes de extracción","Crea solicitudes de extracción sin necesidad de empujar cambios primero","Utiliza comandos no interactivos para automatizar flujos de trabajo"],"fr":["Créez des demandes d''extraction de manière interactive","Définissez des titres et des descriptions personnalisés pour les demandes d''extraction","Sélectionnez des branches de base et des réviseurs pour les demandes d''extraction","Créez des demandes d''extraction sans avoir à pousser les modifications tout d''abord","Utilisez des commandes non interactives pour automatiser les flux de travail"],"de":["Erstellen Sie Pull-Requests interaktiv","Legen Sie benutzerdefinierte Titel und Beschreibungen für Pull-Requests fest","Wählen Sie Basiszweige und Überprüfer für Pull-Requests","Erstellen Sie Pull-Requests ohne vorherige Push-Vorgänge","Verwenden Sie nicht-interaktive Befehle, um Workflows zu automatisieren"],"pt":["Criação de pull requests de forma interativa","Criação de pull requests de forma não interativa","Suporte à autenticação com GitHub CLI","Integração com a Printful API","Suporte à criação de merges","Interface de linha de comando"],"ru":["Создание запросов на слияние в интерактивном режиме","Создание запросов на слияние в неинтерактивном режиме","Поддержка аутентификации с помощью GitHub CLI","Интеграция с Printful API","Поддержка создания слияний","Интерфейс командной строки"],"ar":["إنشاء طلبات سحب بشكل تفاعلي","إنشاء طلبات سحب بشكل غير تفاعلي","دعم التحقق مع جيت هاب CLI","التكامل مع Printful API","دعم إنشاء دمج","واجهة سطر الأوامر"]},"keywords":{"zh":["GitHub SDK Wrapper","Printful API","GitHub CLI","Pull Request","Merge","SDK","API","GitHub","Printful"],"ja":["GitHub SDK Wrapper","Printful API","GitHub CLI","Pull Request","Merge","SDK","API","GitHub","Printful"],"ko":["GitHub SDK Wrapper","Printful API","GitHub CLI","Pull Request","Merge","SDK","API","GitHub","Printful"],"es":["SDK de GitHub","Printful API","solicitudes de extracción","fusiones","desarrollo de software","automatización de flujos de trabajo","integración de API"],"fr":["Wrapper SDK GitHub","Printful API","demandes d''extraction","fusions","développement de logiciels","automatisation de flux de travail","intégration d''API"],"de":["GitHub SDK-Wrapper","Printful API","Pull-Requests","Merge-Anfragen","Softwareentwicklung","Automatisierung von Workflows","API-Integration"],"pt":["github sdk","printful api","pull requests","merges","github cli","autenticação","integração","desenvolvimento","ferramentas de desenvolvimento"],"ru":["github sdk","printful api","запросы на слияние","слияния","github cli","аутентификация","интеграция","разработка","инструменты разработки"],"ar":["جيت هاب sdk","برنتفول api","طلبات سحب","دمج","جيت هاب cli","التحقق","التكامل","التطوير","أدوات التطوير"]}},"owner":"grenovales","repo":"printful-client","repoPath":"grenovales/printful-client","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.471Z","topics":[],"category":"community","skillMd":{"name":"github","description":"Create, review, and merge GitHub pull requests using GitHub CLI and best practices. Use when the user asks to open a PR, review a PR, merge a branch, squash merge, or work with GitHub pull requests and merges.","bodyPreview":"# GitHub Pull Requests and Merges\n\n## Prerequisites\n\n- [GitHub CLI](https://cli.github.com/) (`gh`) installed and authenticated: `gh auth login`\n\n## Creating a Pull Request\n\n### From current branch (after push)\n\n```bash\ngh pr create\n```\n\nInteractive prompts for title, body, base branch, and reviewers.\n\n### Non-interactive\n\n```bash\ngh pr create --title \"feat: add X\" --body \"Description of changes\" --base main\n```\n\n### From a branch without pushing first\n\n```bash\ngh pr create --fill   # Uses commi","body":"# GitHub Pull Requests and Merges\n\n## Prerequisites\n\n- [GitHub CLI](https://cli.github.com/) (`gh`) installed and authenticated: `gh auth login`\n\n## Creating a Pull Request\n\n### From current branch (after push)\n\n```bash\ngh pr create\n```\n\nInteractive prompts for title, body, base branch, and reviewers.\n\n### Non-interactive\n\n```bash\ngh pr create --title \"feat: add X\" --body \"Description of changes\" --base main\n```\n\n### From a branch without pushing first\n\n```bash\ngh pr create --fill   # Uses commit messages for title/body; pushes if needed\n```\n\n### Draft PR\n\n```bash\ngh pr create --draft\n```\n\n## Reviewing a Pull Request\n\n### Check out a PR locally\n\n```bash\ngh pr checkout <pr-number>\n# or\ngh pr checkout 42\n```\n\n### View PR details\n\n```bash\ngh pr view <pr-number>\ngh pr view --web   # Open in browser\n```\n\n### List PRs\n\n```bash\ngh pr list                    # Open PRs\ngh pr list --state merged     # Merged PRs\ngh pr list --author @me       # Your PRs\n```\n\n### Add a review comment (from CLI)\n\n```bash\ngh pr review <pr-number> --comment --body \"LGTM\"\ngh pr review <pr-number> --approve --body \"Approved\"\ngh pr review <pr-number> --request-changes --body \"Please fix X\"\n```\n\n## Merging a Pull Request\n\n### Merge with default strategy (repo setting)\n\n```bash\ngh pr merge <pr-number>\n```\n\n### Merge strategies\n\n| Strategy   | Flag              | Result |\n|-----------|-------------------|--------|\n| Merge     | `--merge`         | Creates a merge commit |\n| Squash    | `--squash`        | Single commit from PR |\n| Rebase    | `--rebase`        | Rebase PR commits onto base |\n\nExamples:\n\n```bash\ngh pr merge 42 --squash --delete-branch\ngh pr merge 42 --merge\ngh pr merge 42 --rebase\n```\n\n### Common merge options\n\n- `--delete-branch` — Delete the branch after merge (local and remote when using squash/merge).\n- `--auto` — Enable auto-merge when checks pass (GitHub will merge automatically).\n- `--admin` — Merge even if branch is not up to date (use with care).\n\n### Merge without merging (close as not merged)\n\n```bash\ngh pr close <pr-number>\n```\n\n## Workflow checklist\n\n**Before creating a PR:**\n- [ ] Branch is up to date with base (e.g. `git fetch origin && git rebase origin/main`)\n- [ ] Commits are logical; consider squash if many small fixes\n- [ ] Title and description explain what and why\n\n**Before merging:**\n- [ ] CI passes\n- [ ] Review approved (if required)\n- [ ] Choose correct strategy: squash for single-feature PRs, merge when preserving history\n\n## Quick reference\n\n| Task              | Command |\n|-------------------|---------|\n| Create PR         | `gh pr create` |\n| Checkout PR       | `gh pr checkout <n>` |\n| View PR           | `gh pr view <n>` |\n| Merge (squash)    | `gh pr merge <n> --squash --delete-branch` |\n| Merge (merge)     | `gh pr merge <n> --merge` |\n| List open PRs     | `gh pr list` |\n"},"lastSynced":"2026-02-18T08:53:09.197Z","agentAnalysis":{"suitability":{"en":"Essential for Code Review Agents automating GitHub pull request workflows and repository management.","zh":"适用于自动化 GitHub 拉取请求工作流和仓库管理的代码审查代理。","ja":"GitHub のプルリクエストワークフローとリポジトリ管理を自動化するコードレビュー エージェントに不可欠です。","ko":"GitHub 풀 리퀘스트 워크플ロー 및 리포지토리 관리를 자동화하는 코드 리뷰 에이전트에 필수적입니다.","es":"Esencial para los agentes de revisión de código que automatizan flujos de trabajo de solicitudes de extracción de GitHub y administración de repositorios.","fr":"Essentiel pour les agents de révision de code automatisant les flux de travail de demande de tirage GitHub et la gestion de référentiels.","de":"Wesentlich für Code-Review-Agents, die GitHub-Pull-Request-Workflows und Repository-Management automatisieren.","pt":"Essencial para Agentes de Revisão de Código que automatizam fluxos de trabalho de solicitação de pull do GitHub e gerenciamento de repositórios.","ru":"Необходим для агентов проверки кода, автоматизирующих рабочие процессы запросов на вытягивание GitHub и управление репозиториями.","ar":"ضروري لمحللين مراجعة الكود الذين يؤتمون سير عمل طلبات السحب على منصة GitHub وإدارة المستودعات."},"recommendation":{"en":"Enables direct GitHub CLI integration for automated pull request creation, branch management, and repository operations. Provides non-interactive command execution with flags like --title, --body, and --base for CI/CD pipeline integration.","zh":"启用直接 GitHub CLI 集成以实现自动化拉取请求创建、分支管理和仓库操作。提供非交互式命令执行，带有 --title、--body 和 --base 标志用于 CI/CD 流水线集成。","ja":"自動化されたプルリクエストの作成、ブランチ管理、リポジトリ操作のための直接の GitHub CLI 統合を可能にします。--title、--body、--base などのフラグを使用した非対話型のコマンド実行を提供し、CI/CD パイプライン統合に使用します。","ko":"자동화된 풀 리퀘스트 생성, 브랜치 관리 및 리포지토리 작업을 위한 직접 GitHub CLI 통합을 가능하게 합니다. --title, --body 및 --base와 같은 플래그를 사용하여 비대화식 명령 실행을 제공하며, CI/CD 파이프라인 통합에 사용됩니다.","es":"Permite la integración directa de GitHub CLI para la creación automática de solicitudes de extracción, gestión de ramas y operaciones de repositorio. Proporciona la ejecución de comandos no interactivos con indicadores como --title, --body y --base para la integración de pipelines de CI/CD.","fr":"Permet l''intégration directe de GitHub CLI pour la création automatisée de demandes de tirage, la gestion de branches et les opérations de référentiel. Fournit l''exécution de commandes non interactives avec des indicateurs tels que --title, --body et --base pour l''intégration de pipelines CI/CD.","de":"Ermöglicht die direkte Integration von GitHub CLI für die automatisierte Erstellung von Pull-Requests, die Verwaltung von Branches und Repository-Vorgängen. Bietet die nicht-interaktive Ausführung von Befehlen mit Flags wie --title, --body und --base für die Integration von CI/CD-Pipelines.","pt":"Permite integração direta com a CLI do GitHub para criação automática de solicitações de pull, gerenciamento de branches e operações de repositório. Fornece execução de comandos não interativos com flags como --title, --body e --base para integração de pipeline CI/CD.","ru":"Позволяет напрямую интегрироваться с GitHub CLI для автоматизированного создания запросов на вытягивание, управления ветками и операциями с репозиторием. Предоставляет неинтерактивное выполнение команд с флагами như --title, --body и --base для интеграции с конвейером CI/CD.","ar":"يسمح بالتكامل المباشر مع واجهة سطر الأوامر GitHub لإنشاء طلبات السحب自动يا وإدارة الفروع وعمليات المستودع. يوفر تنفيذ أوامر غير تفاعلية مع علامات مثل --title و --body و --base لتكامل أنابيب CI/CD."},"useCases":{"en":["Automating pull request creation from CI pipelines","Managing branch workflows without manual pushes","Generating standardized PR templates with --fill flag"],"zh":["从 CI 流水线自动化拉取请求创建","无需手动推送即可管理分支工作流","使用 --fill 标志生成标准化的 PR 模板"],"ja":["CI パイプラインからのプルリクエストの自動化された作成","手動プッシュ不要でブランチワークフローを管理する","--fill フラグを使用して標準化された PR テンプレートを生成する"],"ko":["CI 파이프라인에서 풀 리퀘스트 자동 생성","수동 푸시 없이 브랜치 워크플ロー 관리","--fill 플래그를 사용하여 표준화된 PR 템플릿 생성"],"es":["Automatizar la creación de solicitudes de extracción desde pipelines de CI","Administrar flujos de trabajo de ramas sin empujones manuales","Generar plantillas de PR estandarizadas con la bandera --fill"],"fr":["Automatiser la création de demandes de tirage à partir de pipelines de CI","Gérer les flux de travail de branches sans poussées manuelles","Générer des modèles de PR standardisés avec l''indicateur --fill"],"de":["Automatisieren der Erstellung von Pull-Requests aus CI-Pipelines","Verwalten von Branch-Workflows ohne manuelle Push-Vorgänge","Erstellen standardisierter PR-Vorlagen mit dem Flag --fill"],"pt":["Automação da criação de solicitações de pull a partir de pipelines CI","Gerenciamento de fluxos de trabalho de branches sem pushes manuais","Geração de modelos de PR padronizados com a flag --fill"],"ru":["Автоматизация создания запросов на вытягивание из конвейеров CI","Управление рабочими процессами веток без ручных пуширования","Генерация стандартизированных шаблонов PR с флагом --fill"],"ar":["توفير автомatisation لإنشاء طلبات السحب من أنابيب CI","إدارة سير عمل الفروع بدون ضغطة يدوية","توليد قوالب طلبات السحب الموحدة مع علم --fill"]},"limitations":{"en":["Requires GitHub CLI (gh) installation","Needs prior authentication via gh auth login","Limited to GitHub platform functionality"],"zh":["需要安装 GitHub CLI（gh）","需要通过 gh auth login 进行身份验证","仅限 GitHub 平台功能"],"ja":["GitHub CLI（gh）をインストールする必要がある","gh auth login を使用して認証する必要がある","GitHub プラットフォームの機能に限定される"],"ko":["GitHub CLI(gh) 설치 필요","gh auth login을 통한 인증 필요","GitHub 플랫폼 기능에限定됨"],"es":["Requiere la instalación de GitHub CLI (gh)","Necesita una autenticación previa a través de gh auth login","Limitado a la funcionalidad de la plataforma de GitHub"],"fr":["Nécessite l''installation de GitHub CLI (gh)","Nécessite une authentification préalable via gh auth login","Limité à la fonctionnalité de la plateforme GitHub"],"de":["Benötigt die Installation von GitHub CLI (gh)","Benötigt eine vorherige Authentifizierung über gh auth login","Begrenzt auf die Funktionalität der GitHub-Plattform"],"pt":["Requer instalação da CLI do GitHub (gh)","Necessita de autenticação prévia via gh auth login","Limitado à funcionalidade da plataforma GitHub"],"ru":["Требует установки GitHub CLI (gh)","Требует предварительной аутентификации через gh auth login","Ограничен функциональностью платформы GitHub"],"ar":["يتطلب تثبيت واجهة سطر الأوامر GitHub (gh)","يحتاج إلى مصادقة مسبقة عبر gh auth login","محدود بالوظائف المنصة GitHub"]},"version":3},"qualityScore":0}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('grenovales/printful-client/typescript', 'community', 'grenovales', 'printful-client', 'grenovales/printful-client', 'typescript', 0, 0, 35, '2026-02-18T01:08:43.471Z', '2026-02-18T08:53:23.539Z', NULL, '{"id":"grenovales/printful-client/typescript","name":"typescript","description":{"zh":"TypeScript SDK Wrapper Printful API, .ts","ja":"TypeScript SDK Wrapper Printful API, .ts","ko":"TypeScript SDK Wrapper Printful API, .ts","es":"TypeScript es un superset de JavaScript que mejora la seguridad de tipos y la productividad. Nuestro SDK para la API de Printful utiliza TypeScript para proporcionar una mejor experiencia de desarrollo","fr":"TypeScript est un sur-ensemble de JavaScript qui améliore la sécurité des types et la productivité. Notre SDK pour l''API Printful utilise TypeScript pour offrir une meilleure expérience de développement","de":"TypeScript ist ein Superset von JavaScript, das die Typsicherheit und Produktivität verbessert. Unser SDK für die Printful-API verwendet TypeScript, um eine bessere Entwicklungserfahrung zu bieten","pt":"TypeScript é uma linguagem de programação que adiciona tipos estáticos ao JavaScript. O SDK Wrapper para a API do Printful permite desenvolver aplicações robustas e escaláveis.","ru":"TypeScript - это язык программирования, добавляющий статические типы к JavaScript. Оболочка SDK для API Printful позволяет разрабатывать масштабируемые приложения.","ar":"تايب سكريبت هي لغة برمجة تضيف أنواع ثابتة إلى جافا سكريبت. غلاف SDK لبروتوكول Printful API يسمح بإنشاء تطبيقات قوية وموسعة.","en":"SDK Wrapper for the Printful API"},"seo":{"title":{"zh":"TypeScript SDK Wrapper","ja":"TypeScript SDK ","ko":"TypeScript SDK ","es":"TypeScript: SDK para la API de Printful","fr":"TypeScript : Wrapper SDK pour l''API Printful","de":"TypeScript: SDK-Wrapper für die Printful-API","pt":"Desenvolvimento com TypeScript: SDK Wrapper para Printful...","ru":"TypeScript: Оболочка SDK для Printful API","ar":"تايب سكريبت: غلاف SDK لبروتوكول Printful API","en":"typescript"},"description":{"zh":"TypeScript SDK Wrapper Printful API, .ts","ja":"TypeScript SDK Wrapper Printful API, .ts","ko":"TypeScript SDK Wrapper Printful API, .ts","es":"TypeScript es un superset de JavaScript que mejora la seguridad de tipos y la productividad. Nuestro SDK para la API de Printful utiliza TypeScript para prop...","fr":"TypeScript est un sur-ensemble de JavaScript qui améliore la sécurité des types et la productivité. Notre SDK pour l''API Printful utilise TypeScript pour off...","de":"TypeScript ist ein Superset von JavaScript, das die Typsicherheit und Produktivität verbessert. Unser SDK für die Printful-API verwendet TypeScript, um eine ...","pt":"TypeScript é uma linguagem de programação que adiciona tipos estáticos ao JavaScript. O SDK Wrapper para a API do Printful permite desenvolver aplicações rob...","ru":"TypeScript - это язык программирования, добавляющий статические типы к JavaScript. Оболочка SDK для API Printful позволяет разрабатывать масштабируемые прило...","ar":"تايب سكريبت هي لغة برمجة تضيف أنواع ثابتة إلى جافا سكريبت. غلاف SDK لبروتوكول Printful API يسمح بإنشاء تطبيقات قوية وموسعة.","en":"SDK Wrapper for the Printful API"},"definition":{"en":"SDK Wrapper for the Printful API"},"features":{"zh":["TypeScript","Printful API","SDK","Wrapper","Strict Typing"],"ja":["TypeScript","Printful API","SDK","Wrapper","Strict Typing"],"ko":["TypeScript","Printful API","SDK","Wrapper","Strict Typing"],"es":["Tipado estricto con strict: true","Inferencia de tipos para variables locales","Uso de unknown en lugar de any","Mejora de la seguridad de tipos","Compatibilidad con la API de Printful"],"fr":["Typage strict avec strict: true","Inférence de types pour les variables locales","Utilisation de unknown au lieu de any","Amélioration de la sécurité des types","Compatibilité avec l''API Printful"],"de":["Strenger Typing mit strict: true","Typinferenz für lokale Variablen","Verwendung von unknown anstelle von any","Verbesserung der Typsicherheit","Kompatibilität mit der Printful-API"],"pt":["Tipagem estática","Interface e genéricos","Tipos seguros","Correção de erros de tipo","Melhoria da segurança de tipo"],"ru":["Статическая типизация","Интерфейсы и генерики","Безопасные типы","Исправление ошибок типов","Улучшение безопасности типов"],"ar":["التنميق الثابت","الواجهة والجENERICS","أنواع آمنة","تصحيح أخطاء النوع","تحسين أمان النوع"]},"keywords":{"zh":["TypeScript","Printful API","SDK","Wrapper","Strict Typing","TypeScript","TypeScript"],"ja":["TypeScript","Printful API","SDK","Wrapper","Strict Typing","TypeScript","TypeScript"],"ko":["TypeScript","Printful API","SDK","Wrapper","Strict Typing","TypeScript","TypeScript"],"es":["TypeScript","SDK Printful","tipado estricto","seguridad de tipos","desarrollo de software","JavaScript","API Printful","desarrollo web"],"fr":["TypeScript","SDK Printful","typage strict","sécurité des types","développement de logiciels","JavaScript","API Printful","développement web"],"de":["TypeScript","SDK Printful","strenge Typisierung","Typsicherheit","Softwareentwicklung","JavaScript","Printful-API","Webentwicklung"],"pt":["TypeScript","SDK Wrapper","Printful API","Desenvolvimento de aplicações","Tipagem estática","Segurança de tipo","JavaScript","Linguagem de programação"],"ru":["TypeScript","Оболочка SDK","Printful API","Разработка приложений","Статическая типизация","Безопасность типов","JavaScript","Язык программирования"],"ar":["تايب سكريبت","غلاف SDK","بروتوكول Printful API","تطوير التطبيقات","التنميق الثابت","أمان النوع","جافا سكريبت","لغة برمجة"]}},"owner":"grenovales","repo":"printful-client","repoPath":"grenovales/printful-client","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.471Z","topics":[],"category":"community","skillMd":{"name":"typescript","description":"Apply TypeScript best practices for strict typing, explicit public API types, and declaration-safe code. Use when writing or editing TypeScript files, adding or refining types, or when the user asks for TypeScript guidance.","bodyPreview":"# TypeScript\n\n## When to Apply\n\n- Writing or editing `.ts` files\n- Adding types, interfaces, or generics\n- User asks for TypeScript help or strict typing\n- Fixing type errors or improving type safety\n\n## Core Principles\n\n### 1. Strict Typing\n\n- Rely on `strict: true` (or equivalent). Do not disable strict checks to fix errors.\n- Prefer explicit parameter and return types for **public** functions and methods. Allow inference for obvious locals.\n- Use `unknown` instead of `any` when the type is tr","body":"# TypeScript\n\n## When to Apply\n\n- Writing or editing `.ts` files\n- Adding types, interfaces, or generics\n- User asks for TypeScript help or strict typing\n- Fixing type errors or improving type safety\n\n## Core Principles\n\n### 1. Strict Typing\n\n- Rely on `strict: true` (or equivalent). Do not disable strict checks to fix errors.\n- Prefer explicit parameter and return types for **public** functions and methods. Allow inference for obvious locals.\n- Use `unknown` instead of `any` when the type is truly unknown; narrow before use.\n\n### 2. Avoid `any`\n\n- Do not introduce `any` unless the user explicitly requests it or a library has no types.\n- For untyped external values: use `unknown` and type guards, or define a minimal interface.\n- For generic “pass-through” data: use generics or a specific type rather than `any`.\n\n### 3. Public API and Declarations\n\n- Exported functions, classes, and their public methods should have explicit return types so `.d.ts` output is clear.\n- Optional parameters: use `param?: Type`; for “optional but can be undefined” use `param: Type | undefined` when that distinction matters.\n- Prefer `interface` for object shapes that are part of the public API; use `type` for unions, mapped types, or when extending with intersections.\n\n### 4. Classes and Visibility\n\n- Use `public`, `private`, or `protected` so intent is clear and declaration files reflect the real API.\n- Mark constructor-only dependencies (e.g. helpers) as `private` or `protected`; expose only what callers need.\n\n### 5. Async and Promises\n\n- Return `Promise<T>` explicitly from async functions that are part of the public API.\n- Do not use `Promise<any>`; use a concrete `T` or `unknown` and narrow.\n\n### 6. Null and Undefined\n\n- Use `strictNullChecks` (on when `strict` is true). Handle `null` and `undefined` explicitly.\n- Prefer optional chaining (`?.`) and nullish coalescing (`??`) over ad-hoc checks when it keeps code clear.\n\n## Patterns\n\n### Typing function parameters and returns (public API)\n\n```typescript\n// Prefer: explicit return type for public API\nexport function getItem(id: string): Promise<Item | null> {\n  return fetchItem(id);\n}\n\n// Avoid: no return type on exported function\nexport function getItem(id: string) {\n  return fetchItem(id);\n}\n```\n\n### Handling unknown data\n\n```typescript\n// Prefer: unknown + guard\nfunction parsePayload(data: unknown): Config {\n  if (typeof data !== \"object\" || data === null || !(\"key\" in data)) {\n    throw new Error(\"Invalid config\");\n  }\n  return data as Config;\n}\n\n// Avoid: any\nfunction parsePayload(data: any): Config {\n  return data;\n}\n```\n\n### Optional vs undefined\n\n```typescript\n// Optional (can be omitted)\nfunction create(options?: { name: string }) {}\n\n// Explicit undefined in type\nfunction find(id: string): Result | undefined {}\n```\n\n## Project Conventions (this repo)\n\n- Target and module: follow `tsconfig.json` (e.g. `target`, `module`, `declaration`).\n- Use `@typescript-eslint` recommended rules; do not disable type-aware rules without good reason.\n- Keep declaration output in mind: exported names and their types become the public contract.\n\n## Summary Checklist\n\n- [ ] No new `any`; use `unknown` and narrow if needed\n- [ ] Public/exported functions and methods have explicit return types\n- [ ] Optional parameters use `?`; null/undefined handled under strict null checks\n- [ ] Class members have appropriate visibility (`public` / `private` / `protected`)\n- [ ] Async public API returns `Promise<ConcreteType>` (not `Promise<any>`)\n"},"lastSynced":"2026-02-18T08:53:23.539Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Generation Agents requiring strict typing and TypeScript expertise for SDK development and maintenance.","zh":"适用于需要严格类型和TypeScript专业知识的代码生成代理，用于SDK开发和维护。","ja":"コード生成エージェントが厳格な型付けとTypeScriptの専門知識を必要とするSDKの開発とメンテナンスに最適です。","ko":"코드 생성 에이전트가 엄격한 타이핑과 TypeScript 전문 지식을 필요로 하는 SDK 개발 및 유지 관리에 적합합니다.","es":"Ideal para agentes de generación de código que requieren tipado estricto y experiencia en TypeScript para el desarrollo y mantenimiento de SDK.","fr":"Idéal pour les agents de génération de code nécessitant un typage strict et une expertise TypeScript pour le développement et la maintenance de SDK.","de":"Ideal für Code-Generierungsagenten, die strenges Typing und TypeScript-Expertise für die SDK-Entwicklung und -Wartung erfordern.","pt":"Ideal para Agentes de Geração de Código que exigem tipagem estrita e experiência em TypeScript para desenvolvimento e manutenção de SDKs.","ru":"Идеально подходит для агентов генерации кода, требующих строгой типизации и экспертных знаний TypeScript для разработки и сопровождения SDK.","ar":"مثالي لوكلاء توليد التعليمات البرمجية التي تتطلب كتابة صارمة وخبرة في TypeScript لتطوير وصيانة SDK."},"recommendation":{"en":"Empowers agents to enforce strict typing, utilize explicit parameter and return types, and leverage generics for robust SDK wrappers like the Printful API, ensuring type safety and reducing errors through `unknown` type usage instead of `any`.","zh":"赋予代理人强制严格类型、利用明确的参数和返回类型以及利用泛型来创建健壮的SDK包装器（如Printful API），从而确保类型安全并通过使用`unknown`类型代替`any`来减少错误。","ja":"エージェントが厳格な型付けを実施し、明示的なパラメータと戻り値の型を利用し、Printful APIなどのロバストなSDKラッパーを作成するためにジェネリクスを利用できるようにし、`unknown`型の使用によって`any`を代替し、エラーを減らし、型の安全性を確保します。","ko":"에이전트가 엄격한 타이핑을 강제하고, 명시적인 매개 변수 및 반환 타입을 활용하며, Printful API와 같은 강력한 SDK 래퍼를 생성하기 위해 제네릭스를 활용할 수 있도록 함으로써 `unknown` 타입을 사용하여 `any`를 대체하고, 오류를 줄이고, 타입 안전성을 보장합니다.","es":"Habilita a los agentes a aplicar un tipado estricto, utilizar parámetros y tipos de retorno explícitos y aprovechar los genéricos para crear envolturas de SDK robustas como la API de Printful, garantizando la seguridad de los tipos y reduciendo los errores a través del uso del tipo `unknown` en lugar de `any`.","fr":"Permet aux agents d''appliquer un typage strict, d''utiliser des paramètres et des types de retour explicites et de tirer parti des génériques pour créer des enveloppes de SDK robustes comme l''API Printful, garantissant la sécurité des types et réduisant les erreurs grâce à l''utilisation du type `unknown` au lieu de `any`.","de":"Ermächtigt Agenten, strenges Typing durchzusetzen, explizite Parameter- und Rückgabetypen zu nutzen und Generics für robuste SDK-Wrapper wie die Printful-API zu verwenden, um die Typsicherheit zu gewährleisten und Fehler durch den Einsatz des `unknown`-Typs anstelle von `any` zu reduzieren.","pt":"Capacita os agentes a impor tipagem estrita, utilizar parâmetros explícitos e tipos de retorno, e aproveitar genéricos para wrappers de SDK robustos como a API Printful, garantindo segurança de tipo e reduzindo erros através do uso do tipo `unknown` em vez de `any`.","ru":"Позволяет агентам применять строгую типизацию, использовать явные параметры и возвращаемые типы, а также применять дженерики для создания надежных оберток SDK, таких как Printful API, обеспечивая безопасность типов и сокращая количество ошибок за счет использования типа `unknown` вместо `any`.","ar":"يمكن الوكلاء من فرض الكتابة الصارمة، واستخدام معلمات صريحة وأنواع الإرجاع، والاستفادة من الأنواع العامة (Generics) للحصول على أغلفة SDK قوية مثل واجهة برمجة تطبيقات Printful، مما يضمن سلامة النوع ويقلل الأخطاء من خلال استخدام نوع `unknown` بدلاً من `any`."},"useCases":{"en":["Writing and editing `.ts` files with strict typing","Adding types, interfaces, or generics to existing codebases","Debugging type errors and improving overall type safety in SDK wrappers"],"zh":["使用严格类型编写和编辑`.ts`文件","向现有代码库添加类型、接口或泛型","调试类型错误并提高SDK包装器的整体类型安全性"],"ja":["厳格な型付けで`.ts`ファイルを書き込むおよび編集する","既存のコードベースに型、インターフェイス、またはジェネリクスを追加する","型エラーをデバッグし、SDKラッパーの全体的な型の安全性を向上させる"],"ko":["엄격한 타이핑을 사용하여 `.ts` 파일을 작성하고 편집하는 것","기존 코드베이스에 타입, 인터페이스 또는 제네릭스를 추가하는 것","타입 오류를 디버깅하고 SDK 래퍼의 전반적인 타입 안전성을 향상시키는 것"],"es":["Escribir y editar archivos `.ts` con tipado estricto","Agregar tipos, interfaces o genéricos a código existente","Depurar errores de tipo y mejorar la seguridad de los tipos en general en las envolturas de SDK"],"fr":["Écrire et éditer des fichiers `.ts` avec typage strict","Ajouter des types, des interfaces ou des génériques à des bases de code existantes","Déboguer les erreurs de type et améliorer la sécurité des types en général dans les enveloppes de SDK"],"de":["Schreiben und Bearbeiten von `.ts`-Dateien mit strengem Typing","Hinzufügen von Typen, Schnittstellen oder Generics zu bestehendem Code","Fehlerbehebung von Typfehlern und allgemeine Verbesserung der Typsicherheit in SDK-Wrappern"],"pt":["Escrever e editar arquivos `.ts` com tipagem estrita","Adicionar tipos, interfaces ou genéricos a bases de código existentes","Depurar erros de tipo e melhorar a segurança geral de tipos em wrappers de SDK"],"ru":["Написание и редактирование файлов `.ts` со строгой типизацией","Добавление типов, интерфейсов или дженериков в существующие кодовые базы","Отладка ошибок типов и повышение общей безопасности типов в обертках SDK"],"ar":["كتابة وتحرير ملفات `.ts` بكتابة صارمة","إضافة أنواع أو واجهات أو أنواع عامة (Generics) إلى قواعد التعليمات البرمجية الحالية","تصحيح أخطاء النوع وتحسين سلامة النوع بشكل عام في أغلفة SDK"]},"limitations":{"en":["Requires TypeScript environment","Strict typing must be enabled","Type inference may not always be possible for complex types"],"zh":["需要TypeScript环境","必须启用严格类型","复杂类型可能无法始终推断类型"],"ja":["TypeScript環境が必要","厳格な型付けが有効化される必要がある","複雑な型については、型推論が常に可能ではない"],"ko":["TypeScript 환경이 필요함","엄격한 타이핑을 활성화해야 함","복잡한 타입에 대해 항상 유형 추론이 가능하지는 않음"],"es":["Requiere un entorno de TypeScript","El tipado estricto debe estar habilitado","La inferencia de tipos puede que no siempre sea posible para tipos complejos"],"fr":["Nécessite un environnement TypeScript","Le typage strict doit être activé","L''inférence de types n''est pas toujours possible pour les types complexes"],"de":["Benötigt eine TypeScript-Umgebung","Strenges Typing muss aktiviert sein","Die Typinferenz ist möglicherweise nicht immer möglich für komplexe Typen"],"pt":["Requer ambiente TypeScript","A tipagem estrita deve estar habilitada","A inferência de tipo pode nem sempre ser possível para tipos complexos"],"ru":["Требуется среда TypeScript","Строгая типизация должна быть включена","Вывод типов может быть невозможен для сложных типов"],"ar":["يتطلب بيئة TypeScript","يجب تمكين الكتابة الصارمة","قد لا يكون استنتاج النوع ممكنًا دائمًا للأنواع المعقدة"]},"version":3},"qualityScore":35}');
