INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ShouxinZhang/alpha-game-snake/build-check', 'community', 'ShouxinZhang', 'alpha-game-snake', 'ShouxinZhang/alpha-game-snake', 'build-check', 0, 0, 0, '2026-02-18T01:08:43.475Z', '2026-02-18T09:13:33.050Z', NULL, '{"id":"ShouxinZhang/alpha-game-snake/build-check","name":"build-check","description":{"zh":"构建检查规范是一套代码检查和测试的标准流程，确保代码质量和稳定性。它包括默认命令、补充测试和执行要求。","ja":"ビルド チェック規約は、コードの品質と安定性を確保するためのコード チェックとテストの標準プロセスです。デフォルト コマンド、追加テスト、実行要件を含みます。","ko":"빌드 체크 규약은 코드 품질과 안정성을 보장하는 코드 체크와 테스트의 표준 프로세스입니다. 기본 명령어, 추가 테스트, 실행 요구 사항을 포함합니다.","es":"Build-check es una herramienta que verifica la calidad del código en cada compilación, garantizando la estabilidad y el rendimiento de la aplicación.","fr":"Build-check est un outil qui vérifie la qualité du code à chaque build, garantissant la stabilité et les performances de l''application.","de":"Build-check ist ein Tool, das die Codequalität bei jedem Build überprüft und so die Stabilität und Leistung der Anwendung gewährleistet.","pt":"A ferramenta Build-Check é uma solução para garantir a qualidade do código, executando scripts de verificação e testes automatizados após alterações.","ru":"Инструмент Build-Check является решением для обеспечения качества кода, выполняя скрипты проверки и автоматизированные тесты после изменений.","ar":"أداة Build-Check هي حل لضمان جودة الشفرة، من خلال تشغيل سكريبتات الفحص والاختبارات الآلية بعد التعديلات.","en":""},"seo":{"title":{"zh":"构建检查规范 - Build Check","ja":"ビルド チェック規約 - Build Check","ko":"빌드 체크 규약 - Build Check","es":"Verificación de compilación: build-check","fr":"Vérification de build : build-check","de":"Build-Überprüfung: build-check","pt":"Build-Check: Ferramenta de Verificação de Código","ru":"Build-Check: Инструмент для проверки кода","ar":"بيلد-تشيك: أداة فحص الشفرة","en":"build-check"},"description":{"zh":"构建检查规范是一套代码检查和测试的标准流程，确保代码质量和稳定性。它包括默认命令、补充测试和执行要求。","ja":"ビルド チェック規約は、コードの品質と安定性を確保するためのコード チェックとテストの標準プロセスです。デフォルト コマンド、追加テスト、実行要件を含みます。","ko":"빌드 체크 규약은 코드 품질과 안정성을 보장하는 코드 체크와 테스트의 표준 프로세스입니다. 기본 명령어, 추가 테스트, 실행 요구 사항을 포함합니다.","es":"Build-check es una herramienta que verifica la calidad del código en cada compilación, garantizando la estabilidad y el rendimiento de la aplicación.","fr":"Build-check est un outil qui vérifie la qualité du code à chaque build, garantissant la stabilité et les performances de l''application.","de":"Build-check ist ein Tool, das die Codequalität bei jedem Build überprüft und so die Stabilität und Leistung der Anwendung gewährleistet.","pt":"A ferramenta Build-Check é uma solução para garantir a qualidade do código, executando scripts de verificação e testes automatizados após alterações.","ru":"Инструмент Build-Check является решением для обеспечения качества кода, выполняя скрипты проверки и автоматизированные тесты после изменений.","ar":"أداة Build-Check هي حل لضمان جودة الشفرة، من خلال تشغيل سكريبتات الفحص والاختبارات الآلية بعد التعديلات.","en":""},"definition":{"en":""},"features":{"zh":["默认命令：bash scripts/check_errors.sh","补充测试：npm test","执行要求：每次代码改动后执行","结果记录：将结果记录到 dev log","代码质量保证","稳定性确保"],"ja":["デフォルト コマンド：bash scripts/check_errors.sh","追加テスト：npm test","実行要件：コードの変更後毎に実行","結果記録：結果を dev log に記録","コード品質保証","安定性確保"],"ko":["기본 명령어：bash scripts/check_errors.sh","추가 테스트：npm test","실행 요구 사항：코드 변경 후마다 실행","결과 기록：결과를 dev log에 기록","코드 품질 보증","안정성 보장"],"es":["Verificación de errores en el código","Ejecución de pruebas automatizadas","Registro de resultados en el log de desarrollo","Requisitos de ejecución obligatoria después de cada cambio de código","Repetición de pruebas hasta que se superen todas las verificaciones"],"fr":["Vérification des erreurs dans le code","Exécution de tests automatisés","Enregistrement des résultats dans le journal de développement","Exigences d''exécution obligatoire après chaque modification de code","Répétition des tests jusqu''à ce que toutes les vérifications soient réussies"],"de":["Überprüfung von Fehlern im Code","Ausführung von automatisierten Tests","Aufzeichnung der Ergebnisse im Entwicklungslog","Pflicht zur Ausführung nach jeder Codeänderung","Wiederholung der Tests, bis alle Überprüfungen bestanden sind"],"pt":["Executa scripts de verificação de código","Realiza testes automatizados","Registra resultados em log de desenvolvimento","Exige execução após alterações no código","Requer reparo e re-execução em caso de falha"],"ru":["Выполняет скрипты проверки кода","Проводит автоматизированные тесты","Записывает результаты в журнал разработки","Требует выполнения после изменений в коде","Требует исправления и повторного выполнения в случае неудачи"],"ar":["تنفذ سكريبتات فحص الشفرة","تقوم باختبارات آلية","تسجل النتائج في سجل التطوير","تتطلب التنفيذ بعد التعديلات على الشفرة","تتطلب الإصلاح والتشغيل المتكرر في حالة الفشل"]},"keywords":{"zh":["构建检查规范","代码检查","代码测试","代码质量","代码稳定性","dev log","bash","npm test"],"ja":["ビルド チェック規約","コード チェック","コード テスト","コード 品質","コード 安定性","dev log","bash","npm test"],"ko":["빌드 체크 규약","코드 체크","코드 테스트","코드 품질","코드 안정성","dev log","bash","npm test"],"es":["build-check","verificación de compilación","calidad del código","pruebas automatizadas","registro de resultados","desarrollo de software","herramientas de desarrollo"],"fr":["build-check","vérification de build","qualité du code","tests automatisés","enregistrement des résultats","développement de logiciels","outils de développement"],"de":["build-check","Build-Überprüfung","Codequalität","automatisierte Tests","Aufzeichnung der Ergebnisse","Softwareentwicklung","Entwicklungstools"],"pt":["build-check","verificação de código","testes automatizados","qualidade de código","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["build-check","проверка кода","автоматизированные тесты","качество кода","разработка программного обеспечения","инструменты разработки"],"ar":["بيلد-تشيك","فحص الشفرة","اختبارات آلية","جودة الشفرة","تطوير البرمجيات","أدوات التطوير"]}},"owner":"ShouxinZhang","repo":"alpha-game-snake","repoPath":"ShouxinZhang/alpha-game-snake","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.475Z","topics":[],"category":"community","skillMd":{"name":"build-check","description":"代码构建全链路质量门禁。代码改动后必须执行。","bodyPreview":"# 构建检查规范（通用版）\n\n## 默认命令\n\n```bash\nbash scripts/check_errors.sh\n```\n\n## 补充测试\n\n```bash\nnpm test\n```\n\n## 执行要求\n\n1. 每次代码改动后执行。\n2. 如失败，修复并重跑，直至全部通过。\n3. 将结果记录到 dev log。","body":"# 构建检查规范（通用版）\n\n## 默认命令\n\n```bash\nbash scripts/check_errors.sh\n```\n\n## 补充测试\n\n```bash\nnpm test\n```\n\n## 执行要求\n\n1. 每次代码改动后执行。\n2. 如失败，修复并重跑，直至全部通过。\n3. 将结果记录到 dev log。\n"},"lastSynced":"2026-02-18T09:13:33.050Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring automated build validation and error checking using bash scripts and npm tests.","zh":"适用于需要使用bash脚本和npm测试自动执行构建验证和错误检查的DevOps代理。","ja":"bashスクリプトとnpmテストを使用して自動化されたビルド検証とエラーチェックが必要なDevOpsエージェントに最適です。","ko":"bash 스크립트와 npm 테스트를 사용하여 자동화된 빌드 검증 및 오류 확인이 필요한 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren una validación de compilación automatizada y una verificación de errores utilizando scripts de bash y pruebas de npm.","fr":"Idéal pour les agents DevOps nécessitant une validation de build automatisée et une vérification d''erreurs à l''aide de scripts bash et de tests npm.","de":"Idealerweise für DevOps-Agents, die eine automatisierte Build-Validierung und eine Fehlerüberprüfung mithilfe von Bash-Skripten und npm-Tests benötigen.","pt":"Ideal para Agentes DevOps que exigem validação de compilação automatizada e verificação de erros usando scripts bash e testes npm.","ru":"Идеально для агентов DevOps, требующих автоматизированной проверки сборки и проверки ошибок с помощью скриптов bash и тестов npm.","ar":"مثالي لعميل DevOps الذي يتطلب التحقق التلقائي من البناء و فحص الخطأ باستخدام البرامج النصية bash واختبارات npm."},"recommendation":{"en":"Empowers agents to execute build checks using bash scripts and npm tests, ensuring code integrity and reliability by running scripts like check_errors.sh and capturing results for dev logs.","zh":"赋予代理执行构建检查的能力，使用bash脚本和npm测试，通过运行类似check_errors.sh的脚本并将结果捕获到开发日志中，确保代码的完整性和可靠性。","ja":"bashスクリプトとnpmテストを使用してビルドチェックを実行するエージェントを可能にし、check_errors.shのようなスクリプトを実行して結果を開発ログに記録し、コードの完全性と信頼性を確保します。","ko":"bash 스크립트와 npm 테스트를 사용하여 빌드 확인을 실행하는 에이전트를 가능하게 하며, check_errors.sh와 같은 스크립트를 실행하고 결과를 개발 로그에 기록하여 코드의 무결성과 신뢰성을 보장합니다.","es":"Habilita a los agentes a ejecutar verificaciones de compilación utilizando scripts de bash y pruebas de npm, lo que garantiza la integridad y confiabilidad del código al ejecutar scripts como check_errors.sh y capturar resultados para registros de desarrollo.","fr":"Permet aux agents d''exécuter des vérifications de build en utilisant des scripts bash et des tests npm, garantissant ainsi l''intégrité et la fiabilité du code en exécutant des scripts comme check_errors.sh et en capturant les résultats pour les journaux de développement.","de":"Ermächtigt die Agenten, Build-Prüfungen mithilfe von Bash-Skripten und npm-Tests auszuführen, wodurch die Integrität und Zuverlässigkeit des Codes durch die Ausführung von Skripten wie check_errors.sh und die Erfassung von Ergebnissen für Entwicklungsprotokolle sichergestellt wird.","pt":"Habilita os agentes a executar verificações de compilação usando scripts bash e testes npm, garantindo a integridade e confiabilidade do código, executando scripts como check_errors.sh e capturando os resultados para logs de desenvolvimento.","ru":"Наделяет агентов возможностью выполнять проверки сборки с помощью скриптов bash и тестов npm, обеспечивая целостность и надежность кода, запуская скрипты типа check_errors.sh и захватывая результаты для журналов разработки.","ar":"يمنح العميل القدرة على تشغيل فحص البناء باستخدام البرامج النصية bash واختبارات npm، وضمان سلامة وصلاحية الكود من خلال تشغيل البرامج النصية مثل check_errors.sh وcaptures النتائج لسجلات التطوير."},"useCases":{"en":["Automating build validation after code changes","Executing npm tests for supplementing build checks","Recording build check results in development logs"],"zh":["代码更改后自动执行构建验证","使用npm测试来补充构建检查","将构建检查结果记录到开发日志中"],"ja":["コード変更後の自動ビルド検証","npmテストを使用してビルドチェックを補足する","ビルドチェック結果を開発ログに記録する"],"ko":["코드 변경 후 자동 빌드 검증","npm 테스트를 사용하여 빌드 확인 보완","빌드 확인 결과를 개발 로그에 기록"],"es":["Automatizar la validación de compilación después de los cambios de código","Ejecutar pruebas de npm para complementar las verificaciones de compilación","Grabar los resultados de las verificaciones de compilación en los registros de desarrollo"],"fr":["Automatiser la validation de build après les modifications de code","Exécuter des tests npm pour compléter les vérifications de build","Enregistrer les résultats des vérifications de build dans les journaux de développement"],"de":["Automatisierung der Build-Validierung nach Codeänderungen","Ausführen von npm-Tests zur Ergänzung der Build-Prüfungen","Aufzeichnen der Build-Prüfergebnisse in den Entwicklungsprotokollen"],"pt":["Automatizar a validação de compilação após alterações de código","Executar testes npm para complementar as verificações de compilação","Gravar os resultados das verificações de compilação em logs de desenvolvimento"],"ru":["Автоматизация проверки сборки после изменений кода","Выполнение тестов npm для дополнения проверок сборки","Запись результатов проверок сборки в журналы разработки"],"ar":["التحكم الآلي في التحقق من البناء بعد تغييرات الكود","تشغيل اختبارات npm لتعزيز التحقق من البناء","تسجيل نتائج التحقق من البناء في سجلات التطوير"]},"limitations":{"en":["Requires bash and npm environments","Needs execution after every code modification"],"zh":["需要bash和npm环境","需要在每次代码修改后执行"],"ja":["bashとnpm環境が必要","毎回コード修正後に実行する必要がある"],"ko":["bash와 npm 환경이 필요","마다 코드 수정 후에 실행해야 함"],"es":["Requiere entornos de bash y npm","Necesita ejecución después de cada modificación de código"],"fr":["Nécessite des environnements bash et npm","Nécessite une exécution après chaque modification de code"],"de":["Benötigt Bash- und npm-Umgebungen","Benötigt eine Ausführung nach jeder Codeänderung"],"pt":["Exige ambientes bash e npm","Necessita execução após cada modificação de código"],"ru":["Требует среды bash и npm","Требует выполнения после каждого изменения кода"],"ar":["يتطلب بيئات bash وnpm","يحتاج التنفيذ بعد كل تعديل على الكود"]},"version":3},"qualityScore":0}');
